  body('name')
    .optional()
    .trim()
    .isLength({ min: minLength, max: maxLength })
    .withMessage(`Name must be between ${minLength} and ${maxLength} characters`)
    .matches(/^[a-zA-Z][a-zA-Z0-9\s'_-]*$/)
    .withMessage('Name must start with a letter and can only contain letters, numbers, spaces, apostrophes, hyphens, and underscores')
    .escape(); // Additional XSS prevention

// Email validation with additional security checks
const validateEmail = () =>
  body('email')
    .optional()
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail({
      remove_dots: false,
      remove_extension: false,
      gmail_remove_dots: false,
      gmail_remove_subaddress: false,
    })
    .custom((value) => {
      // Block disposable email domains
      const disposableDomains = ['tempmail.com', '10minutemail.com', 'guerrillamail.com'];
      const emailDomain = value.split('@')[1]?.toLowerCase();
      if (disposableDomains.includes(emailDomain)) {
        throw new Error('Disposable email addresses are not allowed');
      }
      return true;
    })
    .escape();

