    .isLength({ min: minLength, max: maxLength })
    .withMessage(`Name must be between ${minLength} and ${maxLength} characters`)
    .matches(/^[a-zA-Z][a-zA-Z0-9\s'_-]*$/)
    .withMessage('Name must start with a letter and can only contain letters, numbers, spaces, apostrophes, hyphens, and underscores')
